import{_ as r,C as n,o as i,c as l,a2 as d,j as t,a as o,E as a}from"./chunks/framework.sc8Z_ZE3.js";const k=JSON.parse('{"title":"Workspaces and roles","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/workspaces.md","filePath":"concepts/workspaces.md"}'),h={name:"concepts/workspaces.md"};function c(p,e,u,g,f,m){const s=n("Badge");return i(),l("div",null,[e[6]||(e[6]=d('<h1 id="workspaces-and-roles" tabindex="-1">Workspaces and roles <a class="header-anchor" href="#workspaces-and-roles" aria-label="Permalink to &quot;Workspaces and roles&quot;">​</a></h1><p>A <strong>Workspace</strong> is where a team works in Octryx AI: its chats, work items, repositories, knowledge, rules, models and budget. Every area shares the one Workspace switch at the top of the left rail.</p><h2 id="kinds-of-workspace" tabindex="-1">Kinds of Workspace <a class="header-anchor" href="#kinds-of-workspace" aria-label="Permalink to &quot;Kinds of Workspace&quot;">​</a></h2><ul><li><strong>Team</strong> (the default): members with roles; platform admins count as admins in it.</li><li><strong>Private</strong>: only its one owner has a role. Platform admins have none there.</li></ul><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Can</th></tr></thead><tbody><tr><td><strong>Platform admin</strong></td><td>everything across the installation: connections available everywhere, models, policies, the default coding engine</td></tr><tr><td>Workspace <strong>owner</strong> and <strong>admin</strong></td><td>the Workspace&#39;s settings: repositories, the review bot, the Workspace&#39;s connections, which coding engines are allowed, standing approvals</td></tr><tr><td>Workspace <strong>member</strong></td><td>work: chat, start workflows, decide what their role allows, choose a coding engine among the allowed ones</td></tr><tr><td>Workspace <strong>viewer</strong></td><td>read</td></tr></tbody></table><p>On top of roles, a person can hold <strong>functions</strong> that workflows ask for, for example &quot;decide as product owner&quot;. A workflow&#39;s approval names who may decide: a role, a function, the requester, the work item&#39;s owner.</p><h2 id="seats-and-the-governed-route" tabindex="-1">Seats and the governed route <a class="header-anchor" href="#seats-and-the-governed-route" aria-label="Permalink to &quot;Seats and the governed route&quot;">​</a></h2><p>Octryx AI runs coding agents on two routes:</p><ul><li><strong>Seat</strong>: the person&#39;s own subscription (Claude, or ChatGPT for Codex), on their own machine. Seat calls pass the platform&#39;s seat relay for policy, the model allow list, content handling and the transcript; the subscription token is passed on unchanged and never stored. <a href="/docs/install/runners">Server runners</a> never use a seat; a phase there that needs one waits for a <a href="/docs/work/seat-takeover">seat takeover</a>.</li><li><strong>Governed</strong>: company models through the platform&#39;s gateway, billed to the Workspace&#39;s budget.</li></ul><p>Seats are <strong>allowed by default</strong> for Workspaces classified <strong>public</strong> or <strong>internal</strong>, and <strong>off from confidential up</strong>. A Workspace admin can switch them off for any Workspace. Allowing them from confidential up needs a change to the classification rules, not just a switch. A Workspace that requires governed routing, or whose classification cannot be resolved, never allows them: no silent fallback. The Codex seat has its own switch with the same rules. See <a href="/docs/security/data-classes">Data classes</a>.</p>',11)),t("p",null,[e[0]||(e[0]=o("When a seat reaches its usage limit during a run, the run goes on with a company model of the ",-1)),e[1]||(e[1]=t("strong",null,"same class",-1)),e[2]||(e[2]=o(" (a Sonnet-class model for Sonnet, never a bigger one) and returns to the seat after the limit resets. The switch, the model chosen and the return are visible run events, and the company calls count against the run's budget. If the Workspace admits no model of that class, the run pauses and names the reset time. ",-1)),a(s,{type:"built",text:"Built"})]),t("p",null,[e[3]||(e[3]=o("A session that holds a work item on the agent board hands it over when its seat reaches the limit or 99 % of its five-hour or seven-day use; a governed session does the same at its daily budget. By default a person confirms every takeover. With the Workspace's ",-1)),e[4]||(e[4]=t("strong",null,"auto",-1)),e[5]||(e[5]=o(" handoff policy, the item is offered to the colleague whose agent has the most spare allowance, and the next one gets it after 10 minutes without an answer. This is separate from the run fallback above: a run does not wait for a colleague. ",-1)),a(s,{type:"built",text:"Built"})]),e[7]||(e[7]=t("p",null,"Costs are kept apart: real API cost, and for seats the list-price equivalent, per person.",-1)),e[8]||(e[8]=t("h2",{id:"devices",tabindex:"-1"},[o("Devices "),t("a",{class:"header-anchor",href:"#devices","aria-label":'Permalink to "Devices"'},"​")],-1)),e[9]||(e[9]=t("p",null,[o("A "),t("strong",null,"device"),o(" is a developer's machine, registered to one person with "),t("code",null,"octryx-claude device enable"),o(". It connects out to the platform, runs jobs only in folders on its own allow list, and has its own key. See "),t("a",{href:"/docs/install/launcher"},"Launcher and devices"),o(".")],-1))])}const v=r(h,[["render",c]]);export{k as __pageData,v as default};
